create or replace function public.get_business_service_entitlement(p_business_id uuid) returns jsonb language sql security definer set search_path=public,auth,extensions,pg_temp as $$ select jsonb_build_object('business_id',b.id,'business_tier',b.business_tier::text,'service_tier',coalesce(ase.service_tier,case when b.business_tier::text='enterprise' then 'enterprise' when b.business_tier::text='fleet' then 'fleet' when b.business_tier::text='growth' then 'growth' else 'business' end),'location_limit',coalesce(ase.location_limit,case when b.business_tier::text='growth' then 5 else null end),'enterprise_fleet_enabled',coalesce(ase.enterprise_fleet_enabled,b.business_tier::text='enterprise'),'fleet_enabled',coalesce(ase.fleet_enabled,b.business_tier::text in ('fleet','enterprise'))) from public.businesses b left join lateral (select a.* from public.business_members bm join public.account_service_entitlements a on a.account_user_id=bm.user_id where bm.business_id=b.id and bm.role::text in ('owner','admin') order by case when bm.user_id=auth.uid() then 0 else 1 end,case when bm.role::text='owner' then 0 else 1 end,bm.created_at,a.updated_at desc limit 1) ase on true where b.id=p_business_id and (public.is_platform_owner(auth.uid()) or exists(select 1 from public.business_members bm where bm.business_id=b.id and bm.user_id=auth.uid() and bm.role::text in ('owner','admin'))); $$;
create or replace function public.business_intelligence_authorized(p_business_id uuid) returns boolean language sql security definer set search_path=public,auth,extensions,pg_temp as $$ select coalesce((public.get_business_service_entitlement(p_business_id)->>'service_tier') in ('growth','fleet','enterprise'),false); $$;
grant execute on function public.get_business_service_entitlement(uuid) to authenticated;
grant execute on function public.business_intelligence_authorized(uuid) to authenticated; revoke all on function public.get_business_service_entitlement(uuid) from anon; revoke all on function public.business_intelligence_authorized(uuid) from anon;
